using Respira.Doctor.Domain.Enums;
using Respira.ServiceDefaults.Contracts.CQRS;

namespace Respira.Saga.Application.Features.Create.Commands
{
    /// <summary>
    /// Local (never sent over the broker) message produced by the profile creation endpoint that
    /// starts the saga. It carries everything the remaining steps need, including the path
    /// of the avatar the API stored while it waits for the media step.
    /// </summary>
    public record StartCreateCommand : ICommand
    {
        /// <summary>Identifier generated by the endpoint; becomes the saga id.</summary>
        public Guid SagaId { get; set; }

        public string Email { get; set; } = string.Empty;

        /// <summary>
        /// Plaintext password. It is only forwarded to the create account command and is
        /// never stored on the saga state, so it never reaches the saga table.
        /// </summary>
        public string Password { get; set; } = string.Empty;

        public string Phone { get; set; } = string.Empty;

        /// <summary>Whether a doctor or a manager profile should be created.</summary>
        public ProfileRole Role { get; set; }

        public string FirstName { get; set; } = string.Empty;

        public string LastName { get; set; } = string.Empty;

        public List<DegreeType> Degrees { get; set; } = [];

        public AcademicTitleEnum AcademicTitle { get; set; }

        public PositionType Position { get; set; }

        public GenderType Gender { get; set; }

        public string CitizenIdentificationNumber { get; set; } = string.Empty;

        public DateTimeOffset? DateOfBirth { get; set; }

        public string Address { get; set; } = string.Empty;

        /// <summary>Temp file the endpoint wrote the uploaded avatar to.</summary>
        public string? TempAvatarPath { get; set; }
    }
}
